SELECT ?zone ?label ?tsid WHERE {
  ?zone a brick:Zone .
  ?zone rdfs:label ?label .
  FILTER (CONTAINS(?label, "Perimeter_bot_ZN_2") || CONTAINS(?label, "DataCenter_mid_ZN_6"))
  OPTIONAL { ?zone ref:hasExternalReference ?x ; ref:hasTimeseriesId ?tsid . }
}

SELECT ?s ?p ?o WHERE {
  ?s a brick:Zone .
  ?s ?p ?o .
  FILTER (str(?o) LIKE "%ZN_2%")
} LIMIT 20

SELECT ?s ?o WHERE {
  ?s rdfs:label ?o .
  FILTER (CONTAINS(str(?o), "Perimeter") || CONTAINS(str(?o), "DataCenter"))
} LIMIT 40

SELECT ?s ?tsid WHERE {
  ?s brick:isPointOf ?z .
  FILTER (?z IN (
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z03>,
    <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z08>))
  ?s rdf:type ?t .
  FILTER (CONTAINS(str(?t), "Air_Temperature_Sensor"))
  OPTIONAL { ?s ref:hasTimeseriesId ?tsid . }
}

SELECT ?p ?o WHERE {
  ?s rdfs:label "Perimeter_bot_ZN_2" .
  ?z a brick:HVAC_Zone .
